import { test, expect } from '@playwright/test';

test.describe('Table Sorting by Column Headers', () => {
  test.beforeEach(async ({ page }) => {
    // Navigate to a page with a sortable table
    await page.goto('https://example.com/table');
    // Wait for the table to be visible
    await page.getByRole('table').waitFor({ state: 'visible' });
  });

  test('should sort table by clicking column header in ascending order', async ({ page }) => {
    // Get the table
    const table = page.getByRole('table');

    // Get the first column header (e.g., "Name")
    const nameHeader = table.getByRole('columnheader', { name: /name/i });

    // Click the header to sort
    await nameHeader.click();

    // Wait for the table to update
    await page.waitForTimeout(500);

    // Get all rows in the table body
    const rows = table.getByRole('row');

    // Get the first data row (skip header)
    const firstRow = rows.nth(1);
    const firstRowText = await firstRow.textContent();

    // Verify that the table has been sorted (check if first row contains expected data)
    expect(firstRowText).toBeTruthy();
  });

  test('should sort table by clicking column header in descending order', async ({ page }) => {
    // Get the table
    const table = page.getByRole('table');

    // Get the "Price" column header
    const priceHeader = table.getByRole('columnheader', { name: /price/i });

    // Click the header once to sort ascending
    await priceHeader.click();
    await page.waitForTimeout(500);

    // Click the header again to sort descending
    await priceHeader.click();
    await page.waitForTimeout(500);

    // Get all rows in the table body
    const rows = table.getByRole('row');

    // Verify that we have rows
    const rowCount = await rows.count();
    expect(rowCount).toBeGreaterThan(1);

    // Get the first data row
    const firstRow = rows.nth(1);
    const firstRowText = await firstRow.textContent();

    // Verify that the table has been sorted
    expect(firstRowText).toBeTruthy();
  });

  test('should maintain sort order when clicking the same header multiple times', async ({ page }) => {
    // Get the table
    const table = page.getByRole('table');

    // Get the "Date" column header
    const dateHeader = table.getByRole('columnheader', { name: /date/i });

    // Click the header to sort ascending
    await dateHeader.click();
    await page.waitForTimeout(500);

    // Get the first row content
    const rows = table.getByRole('row');
    const firstRowBefore = await rows.nth(1).textContent();

    // Click the header again to sort descending
    await dateHeader.click();
    await page.waitForTimeout(500);

    // Get the first row content after second click
    const firstRowAfter = await rows.nth(1).textContent();

    // Verify that the order has changed (descending vs ascending)
    expect(firstRowBefore).not.toBe(firstRowAfter);
  });

  test('should display sort indicator on active column header', async ({ page }) => {
    // Get the table
    const table = page.getByRole('table');

    // Get the "Status" column header
    const statusHeader = table.getByRole('columnheader', { name: /status/i });

    // Click the header to sort
    await statusHeader.click();
    await page.waitForTimeout(500);

    // Check if the header has a sort indicator (aria-sort attribute or visual indicator)
    const ariaSort = await statusHeader.getAttribute('aria-sort');

    // Verify that the header has a sort indicator
    expect(ariaSort).toMatch(/ascending|descending/);
  });

  test('should sort different columns independently', async ({ page }) => {
    // Get the table
    const table = page.getByRole('table');

    // Get column headers
    const nameHeader = table.getByRole('columnheader', { name: /name/i });
    const priceHeader = table.getByRole('columnheader', { name: /price/i });

    // Sort by name
    await nameHeader.click();
    await page.waitForTimeout(500);

    const rows = table.getByRole('row');
    const firstRowByName = await rows.nth(1).textContent();

    // Sort by price
    await priceHeader.click();
    await page.waitForTimeout(500);

    const firstRowByPrice = await rows.nth(1).textContent();

    // Verify that sorting by different columns produces different results
    expect(firstRowByName).not.toBe(firstRowByPrice);
  });
});
